log = []
class C:
    def __enter__(self):
        log.append("enter")
        return "ctx"
    def __exit__(self, exc_type, exc_value, exc_tb):
        log.append(("exit", exc_type.__name__ if exc_type is not None else None))
        return False
try:
    with C() as value:
        log.append(("body", value))
        raise ValueError("boom")
    log.append("after")
except Exception as e:
    log.append(("escaped", type(e).__name__))
print(log)

